"use strict";
import { Flex, Text, styled as uiStyled } from "ui/src";
import { useMarketContext } from "../../ContextProvider";
import GridItem from "../GridItem";
import { formatUnits } from "viem";
import { NumberType, useFormatter } from "utils/formatNumbers";
const Container = uiStyled(Flex, {
  flexDirection: "column",
  width: "100%",
  marginTop: "$spacing24"
});
const Grid = uiStyled(Flex, {
  display: "flex",
  flexDirection: "row",
  gap: "$spacing36",
  width: "100%",
  $md: {
    flexDirection: "column",
    gap: "$spacing12"
  }
});
function shortenAddress(address) {
  if (!address || address.length < 10) return address;
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}
function formatWithSignificantDigits(value, minDigits = 4) {
  if (value === 0) return "0";
  if (value >= 1) {
    return value.toLocaleString(void 0, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  const magnitude = Math.floor(Math.log10(Math.abs(value)));
  const decimals = Math.max(minDigits, -magnitude + (minDigits - 1));
  return value.toFixed(Math.min(decimals, 10));
}
function formatOraclePrice(oraclePrice, collateralSymbol, loanSymbol, collateralDecimals, loanDecimals) {
  if (oraclePrice === 0n) return { forward: "-", reverse: "-" };
  const exponent = 36 - collateralDecimals + loanDecimals;
  const priceValue = Number(formatUnits(oraclePrice, exponent));
  const inversePrice = priceValue > 0 ? 1 / priceValue : 0;
  return {
    forward: `1 ${collateralSymbol} = ${formatWithSignificantDigits(priceValue)} ${loanSymbol}`,
    reverse: `1 ${loanSymbol} = ${formatWithSignificantDigits(inversePrice)} ${collateralSymbol}`
  };
}
export default function OracleAttributes() {
  const { marketData } = useMarketContext();
  const { formatFiatPrice } = useFormatter();
  if (!marketData) {
    return null;
  }
  const oraclePrices = formatOraclePrice(
    marketData.oraclePrice,
    marketData.collateralToken.symbol,
    marketData.loanToken.symbol,
    marketData.collateralToken.decimals,
    marketData.loanToken.decimals
  );
  return <Container>
      <Text variant="subheading1" color="$neutral1" marginBottom="$spacing16">
        Oracle Attributes
      </Text>
      <Grid>
        <Flex flexDirection="column" flex={1}>
          <GridItem
    label="Oracle address"
    value={shortenAddress(marketData.oracle)}
    copyable
    externalLink
  />
          <GridItem
    label="Collateral token"
    value={shortenAddress(marketData.collateralToken.address)}
    copyable
    externalLink
  />
          <GridItem
    label="Loan token"
    value={shortenAddress(marketData.loanToken.address)}
    copyable
    externalLink
  />
        </Flex>

        <Flex flexDirection="column" flex={1}>
          <GridItem label="Oracle price" value={oraclePrices.forward} />
          <GridItem label="" value={oraclePrices.reverse} />
          <GridItem
    label="Collateral price (USD)"
    value={formatFiatPrice({ price: marketData.collateralPriceUsd, type: NumberType.FiatTokenStats })}
  />
          <GridItem
    label="Loan price (USD)"
    value={formatFiatPrice({ price: marketData.loanPriceUsd, type: NumberType.FiatTokenStats })}
  />
        </Flex>
      </Grid>
    </Container>;
}
